head.script:
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.onpageload = function() {
	var data = [];
	for (var i = 0; i < 20; i++) {
		data.push(i + "");
		data.push(i + "" + "_v");
	}
	dataList1.setData(data);
	var data_grd = [];
	for (var i = 0; i < 100; i++) {
		data_grd.push(i + "_0");
		data_grd.push("");
		data_grd.push("");
		data_grd.push(i + "_3");
	}
	dataList_grd.setData(data_grd);
};
scwin.Dbclick = function(id) {
	var el = scwin.__getDom($p.id + id);
	scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
	if (document.createEventObject) {
		node.fireEvent('ondblclick');
	} else if (document.createEvent) {
		var evt = document.createEvent('MouseEvents');
		evt.initEvent('dblclick', true, false);
		node.dispatchEvent(evt);
	} else if (typeof node.ondblclick == 'function') {
		node.ondblclick();
	}
}
scwin.checkVal = function() {
	if (scwin.__getDom($p.id + 'G_gridView1___checkcombobox_col2_itemTable_1_checkbox').checked == true &&
		scwin.__getDom($p.id + 'G_gridView1___checkcombobox_col2_itemTable_5_checkbox').checked == true &&
		scwin.__getDom($p.id + 'G_gridView1___checkcombobox_col2_itemTable_6_checkbox').checked == true &&
		scwin.__getDom($p.id + 'G_gridView1___checkcombobox_col2_itemTable_7_checkbox').checked == true &&
		scwin.__getDom($p.id + 'G_gridView1___checkcombobox_col2_itemTable_8_checkbox').checked == true) {
		return true;
	} else {
		return false;
	}
}
